"""Minimal progress bars system (no tqdm dependency).

Each worker process reports its progress through a shared counter
(``multiprocessing.Value``) and the master process renders the aggregated bar
on stderr from its display loop.
"""

import multiprocessing
import sys

from .utils import terminal_columns


def is_notebook() -> bool:
    """Detect whether we are running inside a Jupyter notebook."""
    try:
        from IPython import get_ipython

        shell = get_ipython()
        if shell is None:
            return False
        return shell.__class__.__name__ == "ZMQInteractiveShell"
    except Exception:
        return False


class ProgressBars:
    """Aggregated progress bar fed by one shared counter per worker."""

    enabled = True

    def __init__(self, show_progress_bars: bool, nb_workers: int, total: int = None):
        # In a notebook there is no reliable carriage-return redraw: keep it
        # simple and stay silent there (no-op fallback).
        self.show_progress_bars = show_progress_bars and not is_notebook()
        self.nb_workers = nb_workers
        self.total = total if total is not None else nb_workers
        self.global_index = multiprocessing.Value("i", 0)
        self._values = [multiprocessing.Value("i", 0) for _ in range(nb_workers)]
        self._errors = []
        self._finished = False

    def get_next_value(self) -> int:
        """Called once by each worker to get its dedicated counter index."""
        with self.global_index.get_lock():
            index = self.global_index.value
            self.global_index.value += 1
        return index

    def update(self, index: int, value: int = 1) -> None:
        """Increment the progress counter of the given worker."""
        with self._values[index].get_lock():
            self._values[index].value += value

    def set_error(self, index: int, message: str = None) -> None:
        """Record that a worker hit an error."""
        self._errors.append((index, message))

    @property
    def errors(self):
        return list(self._errors)

    @property
    def value(self) -> int:
        return sum(counter.value for counter in self._values)

    def show(self) -> None:
        """Render the aggregated bar on stderr (master process only)."""
        if not self.show_progress_bars:
            return
        total = max(self.total, 1)
        value = min(self.value, total)
        percent = value / total
        columns = terminal_columns()
        prefix = "Progress: |"
        suffix = f"| {percent:6.1%} ({value}/{self.total})"
        bar_length = max(5, columns - len(prefix) - len(suffix) - 2)
        filled = int(bar_length * percent)
        bar = "#" * filled + "-" * (bar_length - filled)
        sys.stderr.write("\r" + prefix + bar + suffix)
        sys.stderr.flush()

    def finish(self) -> None:
        """Draw the final 100% bar and move to a new line."""
        if not self.show_progress_bars or self._finished:
            return
        self._finished = True
        self.show()
        sys.stderr.write("\n")
        sys.stderr.flush()


class NoProgressBars:
    """No-op replacement with the same interface as ProgressBars."""

    enabled = False
    global_index = None
    total = 0

    def get_next_value(self) -> int:
        return 0

    def update(self, index: int, value: int = 1) -> None:
        pass

    def set_error(self, index: int, message: str = None) -> None:
        pass

    @property
    def errors(self):
        return []

    @property
    def value(self) -> int:
        return 0

    def show(self) -> None:
        pass

    def finish(self) -> None:
        pass


def get_progress_bars(progress_bar: bool, nb_workers: int, total: int = None):
    """Factory used by core: real bars when requested, no-op otherwise."""
    if progress_bar:
        return ProgressBars(progress_bar, nb_workers, total=total)
    return NoProgressBars()

