"""Generic chunking helpers and the DataType interface."""

from typing import Any, Dict, List, Tuple

import pandas as pd


def chunk_indices(nb_rows: int, nb_chunks: int) -> List[Tuple[int, int]]:
    """Split ``nb_rows`` rows into at most ``nb_chunks`` contiguous chunks.

    Returns a list of ``(start, end)`` bounds. Never returns empty chunks
    (except when ``nb_rows == 0``, which yields a single ``(0, 0)`` chunk).
    """
    nb_chunks = max(1, nb_chunks)
    if nb_rows <= 0:
        return [(0, 0)]
    nb_chunks = min(nb_chunks, nb_rows)
    base, remainder = divmod(nb_rows, nb_chunks)
    bounds = []
    start = 0
    for index in range(nb_chunks):
        size = base + (1 if index < remainder else 0)
        bounds.append((start, start + size))
        start += size
    return bounds


def groupby_keys(groupby) -> list:
    """Group keys of a (Series|DataFrame)GroupBy, in apply order."""
    return list(groupby.groups.keys())


def groupby_names(groupby) -> list:
    """Names of the grouping levels."""
    return list(groupby._grouper.names)


def concat_grouped_results(keys: list, results: list, names: list):
    """Reassemble per-group results like ``groupby.apply`` does.

    - all scalars -> Series indexed by the group keys
    - Series/DataFrame results -> concatenated with a group-keys outer level
    """
    if all(not isinstance(result, (pd.Series, pd.DataFrame)) for result in results):
        if len(names) == 1:
            index = pd.Index(keys, name=names[0])
        else:
            tuples = [key if isinstance(key, tuple) else (key,) for key in keys]
            index = pd.MultiIndex.from_tuples(tuples, names=names)
        return pd.Series(list(results), index=index)
    return pd.concat(dict(zip(keys, results)), names=names)


def rolling_kwargs(rolling) -> Dict[str, Any]:
    """Constructor kwargs needed to rebuild an equivalent Rolling object."""
    kwargs = {}
    for attribute in (
        "window",
        "min_periods",
        "center",
        "win_type",
        "closed",
        "step",
        "method",
    ):
        if hasattr(rolling, attribute):
            kwargs[attribute] = getattr(rolling, attribute)
    return kwargs


def expanding_kwargs(expanding) -> Dict[str, Any]:
    """Constructor kwargs needed to rebuild an equivalent Expanding object."""
    kwargs = {}
    for attribute in ("min_periods", "method"):
        if hasattr(expanding, attribute):
            kwargs[attribute] = getattr(expanding, attribute)
    return kwargs


class DataType:
    """Interface implemented by every supported pandas data type."""

    @staticmethod
    def get_chunks(nb_workers: int, data, func_args: tuple, func_kwargs: dict) -> list:
        """Split ``data`` into a list of chunks (one work unit per chunk)."""
        raise NotImplementedError

    @staticmethod
    def work(chunk, func, func_args: tuple, func_kwargs: dict):
        """Apply the user function to a single chunk (runs in a worker)."""
        raise NotImplementedError

    @staticmethod
    def reduce(chunks_results: list, data, func_args: tuple, func_kwargs: dict):
        """Combine per-chunk results into the final pandas object."""
        raise NotImplementedError

