"""DataFrameGroupBy / SeriesGroupBy parallel_apply (chunked by group keys)."""

from .generic import DataType, chunk_indices, concat_grouped_results, groupby_keys, groupby_names


class GroupByApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, groupby, func_args, func_kwargs):
        keys = groupby_keys(groupby)
        chunks = []
        for start, end in chunk_indices(len(keys), nb_workers):
            chunks.append([(key, groupby.get_group(key)) for key in keys[start:end]])
        return chunks

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        return [(key, func(group, *func_args, **func_kwargs)) for key, group in chunk]

    @staticmethod
    def reduce(chunks_results, groupby, func_args, func_kwargs):
        items = [item for chunk in chunks_results for item in chunk]
        keys = [key for key, _ in items]
        results = [result for _, result in items]
        return concat_grouped_results(keys, results, groupby_names(groupby))

