from .generic import (
    DataType,
    chunk_indices,
    concat_grouped_results,
    rolling_kwargs,
)


class RollingGroupByApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, rolling_groupby, func_args, func_kwargs):
        grouper = rolling_groupby._grouper
        obj = rolling_groupby.obj
        kwargs = rolling_kwargs(rolling_groupby)
        indices = grouper.indices  # {group key: integer positions into obj}
        keys = list(indices.keys())
        chunks = []
        for start, end in chunk_indices(len(keys), nb_workers):
            items = [(key, obj.iloc[indices[key]]) for key in keys[start:end]]
            chunks.append((items, kwargs))
        return chunks

    @staticmethod
    def work(chunk, func, func_args, func_kwargs):
        items, kwargs = chunk
        return [
            (key, group.rolling(**kwargs).apply(func, *func_args, **func_kwargs))
            for key, group in items
        ]

    @staticmethod
    def reduce(chunks_results, rolling_groupby, func_args, func_kwargs):
        items = [item for chunk in chunks_results for item in chunk]
        keys = [key for key, _ in items]
        results = [result for _, result in items]
        return concat_grouped_results(keys, results, list(rolling_groupby._grouper.names))

