import pandas as pd

from .generic import DataType, chunk_indices, rolling_kwargs


class SeriesRollingApply(DataType):
    @staticmethod
    def get_chunks(nb_workers, rolling, func_args, func_kwargs):
        obj = rolling.obj
        kwargs = rolling_kwargs(rolling)
        window = kwargs.get("window")
        nb_rows = len(obj)

        if not isinstance(window, int) or window < 1:
            # Time-based (offset) windows cannot be safely overlapped:
            # fall back to a single chunk.
            return [(obj, kwargs, 0, nb_rows)]

